"""Naive brute-force reference for the v3 contract, written directly from
PROTOCOL.md with Fraction arithmetic.  Slow, obviously-correct style."""
import json
from fractions import Fraction
from math import isqrt

PAD = 1514


class Invalid(Exception):
    pass


def real_prefix(vals):
    try:
        return vals[:vals.index(PAD)]
    except ValueError:
        return vals


# ---------------- discovery ----------------

def fragments_of(rows, width):
    out = []
    for ri, row in enumerate(rows):
        vals = row['values']
        act = row['activation']
        pre = real_prefix(vals)
        n = len(pre)
        if n == 0:
            continue
        mean = Fraction(sum(act[:n]), n)
        var = sum((Fraction(a) - mean) ** 2 for a in act[:n]) / n
        high = []
        for i in range(n):
            d = Fraction(act[i]) - mean
            high.append(d > 0 and d * d > var)
        i = 0
        while i < n:
            if not high[i]:
                i += 1
                continue
            j = i
            while j < n and high[j]:
                j += 1
            run = j - i
            if run >= 2:
                if run <= width:
                    out.append(((ri, i, run), row['class'], tuple(vals[i:j])))
                else:
                    sums = [sum(act[s:s + width]) for s in range(i, j - width + 1)]
                    best = 0
                    for k in range(1, len(sums)):
                        if sums[k] > sums[best]:
                            best = k
                    s = i + best
                    out.append(((ri, s, width), row['class'], tuple(vals[s:s + width])))
            i = j
    return out


def dist_le(seq1, seq2, eps):
    L = len(seq1)
    sd = 0
    A = 0
    for a, b in zip(seq1, seq2):
        d = abs(a - b)
        if (a < PAD < b) or (b < PAD < a):
            d += 1000
        sd += d * d
        if a == b:
            A += 1
    d2 = Fraction(sd, L) * Fraction(3 ** (2 * A), 5 ** (2 * A))
    e = Fraction(*eps)
    return d2 <= e * e


def trunc_bounds(vals):
    n = len(vals)
    lo = min(vals)
    hi = max(vals)
    mean = Fraction(sum(vals), n)
    var = sum((Fraction(v) - mean) ** 2 for v in vals) / n
    # lower = max(0, trunc(lo - sigma)) = max(0, largest k<=lo with (lo-k)^2>=var)
    k = lo
    while (lo - k) * (lo - k) < var:
        k -= 1
    lower = max(0, k)
    # upper = min(3028, trunc(hi + sigma)) = min(3028, hi + largest t>=0 with t^2<=var)
    t = 0
    while (t + 1) * (t + 1) <= var:
        t += 1
    upper = min(3028, hi + t)
    return [lower, upper]


def cluster_all(frag, eps, ratio):
    """frag: [(cert, cls, seq)] in ID order. Returns (clusters, noise)."""
    from collections import defaultdict
    groups = defaultdict(list)
    per_class = defaultdict(int)
    for idx, (_, cls, seq) in enumerate(frag):
        groups[(cls, len(seq))].append(idx)
        per_class[cls] += 1
    dmin = {}
    for cls, m in per_class.items():
        dmin[cls] = max(2, (m * ratio[0] + ratio[1] - 1) // ratio[1])
    clusters = []
    noise = set()
    for key in sorted(groups):
        cls, L = key
        idxs = groups[key]
        n = len(idxs)
        adj = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                adj[i][j] = dist_le(frag[idxs[i]][2], frag[idxs[j]][2], eps)
        core = [i for i in range(n) if sum(adj[i]) >= dmin[cls]]
        core_set = set(core)
        comp = {}
        comps = []
        for c in core:
            if c in comp:
                continue
            stack = [c]
            comp[c] = len(comps)
            members = [c]
            while stack:
                x = stack.pop()
                for y in core:
                    if y not in comp and adj[x][y]:
                        comp[y] = len(comps)
                        members.append(y)
                        stack.append(y)
            comps.append(sorted(members))
        attach = defaultdict(list)
        for i in range(n):
            if i in comp:
                continue
            cand = {}
            for y in core:
                if adj[i][y]:
                    cid = min(idxs[m] for m in comps[comp[y]])
                    cand[cid] = comp[y]
            if not cand:
                noise.add(idxs[i])
            else:
                best = min(cand)
                attach[best].append(idxs[i])
        for members in comps:
            core_ids = sorted(idxs[m] for m in members)
            cid = core_ids[0]
            member_ids = sorted(core_ids + attach.get(cid, []))
            seqs = [frag[i][2] for i in member_ids]
            ranges = [trunc_bounds([s[j] for s in seqs]) for j in range(L)]
            clusters.append({'id': cid, 'class': cls, 'members': member_ids,
                             'core': core_ids, 'range': ranges, 'length': L})
    clusters.sort(key=lambda c: c['id'])
    return clusters, sorted(noise)


# ---------------- calibration ----------------

def matches(row_vals, pattern):
    pre = real_prefix(row_vals)
    L = len(pattern)
    for s in range(len(pre) - L + 1):
        ok = True
        for j in range(L):
            if not (pattern[j][0] <= pre[s + j] <= pattern[j][1]):
                ok = False
                break
        if ok:
            return True
    return False


def calibrate(clusters, val_rows, n_classes, threshold):
    N = [0] * n_classes
    for row in val_rows:
        N[row['class']] += 1
    for c in clusters:
        h = [0] * n_classes
        for row in val_rows:
            if matches(row['values'], c['range']):
                h[row['class']] += 1
        t = c['class']
        cin = Fraction(h[t], N[t])
        cout = Fraction(0)
        for cls in range(n_classes):
            if cls != t:
                cout = max(cout, Fraction(h[cls], N[cls]))
        score = cin / (cout + Fraction(1, 10000))
        c['hits'] = h
        c['score'] = score
        c['kept'] = score > Fraction(threshold[0], threshold[1])
    kept = [c for c in clusters if c['kept']]
    kept.sort(key=lambda c: (-c['score'], c['id']))
    return [c['id'] for c in kept]


# ---------------- backup tree ----------------

def backup_cert(train_rows, width):
    import numpy as np
    from sklearn.tree import DecisionTreeClassifier
    X = []
    y = []
    for row in train_rows:
        vals = list(row['values'][:width])
        vals += [PAD] * (width - len(vals))
        X.append(vals)
        y.append(row['class'])
    model = DecisionTreeClassifier(max_depth=10, random_state=42, class_weight='balanced')
    model.fit(np.array(X, dtype=np.int64), np.array(y, dtype=np.int64))
    t = model.tree_
    nodes = []
    for i in range(t.node_count):
        if t.children_left[i] == t.children_right[i] == -1:
            v = t.value[i][0]
            best = 0
            for k in range(1, len(v)):
                if v[k] > v[best]:
                    best = k
            nodes.append([int(model.classes_[best])])
        else:
            nodes.append([int(t.feature[i]), int(2 * t.threshold[i]),
                          int(t.children_left[i]), int(t.children_right[i])])
    return nodes


def backup_predict(nodes, feats, width):
    row = list(feats[:width]) + [PAD] * max(0, width - len(feats))
    node = 0
    while len(nodes[node]) == 2 * 2:
        f, t2, l, r = nodes[node]
        node = l if 2 * row[f] <= t2 else r
    return nodes[node][0]


# ---------------- bank tables ----------------

def entry_count(kept, mode, cap):
    if mode == 'range':
        return len(kept)
    K = cap + 1
    total = 0
    by_len = {}
    for c in kept:
        by_len.setdefault(len(c['range']), []).append(c['range'])
    for L in sorted(by_len):
        keys = set()
        for pattern in by_len[L]:
            cols = []
            for lo, hi in pattern:
                cols.append([v for v in range(lo, hi + 1) if v != PAD])
            cur = {()}
            for col in cols:
                nxt = set()
                for t in cur:
                    for v in col:
                        nxt.add(t + (v,))
                cur = nxt
                if len(cur) >= K:
                    break
            keys |= cur
            if len(keys) >= K:
                break
        total += min(len(keys), K)
        if total >= K:
            return K
    return total


# ---------------- replay ----------------

def replay(models, blocks, capacity):
    """models: id -> dict with width, packet_limit, idle_us, kept(priority
    order list of (cid, cls, range)), backup nodes, mode, entries."""
    current = None
    residents = {}     # id -> entries
    pins = {}
    flows = {}
    epochs = {}
    installs = []
    decisions = []

    def usage(ids):
        u = {'range': 0, 'exact': 0}
        for i in ids:
            u[models[i]['mode']] += models[i]['entries']
        return u

    at = 0
    for block in blocks:
        for event in block:
            op = event[0]
            if op == 'install':
                rid = event[1]
                m = models[rid]
                status = 'ok'
                if m['entries'] > capacity[m['mode']]:
                    status = 'oversize'
                else:
                    prospective = set(residents)
                    if current is not None and pins.get(current, 0) == 0:
                        prospective.discard(current)
                    prospective.add(rid)
                    used = usage(prospective)
                    if used['range'] > capacity['range'] or used['exact'] > capacity['exact']:
                        status = 'busy'
                    else:
                        residents = {i: models[i]['entries'] for i in prospective}
                        current = rid
                installs.append({'at': at, 'id': rid, 'status': status,
                                 'resident': sorted(residents),
                                 'used': usage(residents)})
            elif op == 'open':
                fid = event[1]
                if current is None or fid in flows:
                    raise Invalid()
                epoch = epochs.get(fid, 0)
                epochs[fid] = epoch + 1
                flows[fid] = {'epoch': epoch, 'release': current, 'dir': None,
                              'feats': [], 'consumed': 0, 'ts': None, 'done': False}
                pins[current] = pins.get(current, 0) + 1
            elif op == 'packet':
                fid, ts, src, length = event[1], event[2], event[3], event[4]
                if fid not in flows:
                    raise Invalid()
                fl = flows[fid]
                if fl['ts'] is not None and ts < fl['ts']:
                    raise Invalid()
                if fl['done']:
                    fl['ts'] = ts
                else:
                    m = models[fl['release']]
                    prev = fl['ts']
                    consumed = fl['consumed']
                    if consumed >= m['width'] and prev is not None and ts - prev > m['idle_us']:
                        fl['ts'] = ts
                        cls = backup_predict(m['backup'], fl['feats'], m['width'])
                        fl['done'] = True
                        decisions.append({'flow': fid, 'epoch': fl['epoch'],
                                          'release': fl['release'], 'at': at,
                                          'seen': consumed, 'class': cls,
                                          'reason': 'idle', 'rule': None, 'start': None})
                    else:
                        fl['ts'] = ts
                        if fl['dir'] is None:
                            fl['dir'] = src
                        fl['feats'].append(PAD + length if src == fl['dir'] else PAD - length)
                        consumed += 1
                        fl['consumed'] = consumed
                        hit = None
                        for (cid, cls, pat) in m['kept']:
                            L = len(pat)
                            if L > consumed:
                                continue
                            win = fl['feats'][consumed - L:consumed]
                            if all(pat[j][0] <= win[j] <= pat[j][1] for j in range(L)):
                                hit = (cid, cls, L)
                                break
                        if hit is not None:
                            cid, cls, L = hit
                            fl['done'] = True
                            decisions.append({'flow': fid, 'epoch': fl['epoch'],
                                              'release': fl['release'], 'at': at,
                                              'seen': consumed, 'class': cls,
                                              'reason': 'segment', 'rule': cid,
                                              'start': consumed - L})
                        elif consumed > m['packet_limit']:
                            cls = backup_predict(m['backup'], fl['feats'], m['width'])
                            fl['done'] = True
                            decisions.append({'flow': fid, 'epoch': fl['epoch'],
                                              'release': fl['release'], 'at': at,
                                              'seen': consumed, 'class': cls,
                                              'reason': 'limit', 'rule': None, 'start': None})
            else:
                fid = event[1]
                if fid not in flows:
                    raise Invalid()
                fl = flows[fid]
                if not fl['done']:
                    m = models[fl['release']]
                    cls = backup_predict(m['backup'], fl['feats'], m['width'])
                    fl['done'] = True
                    decisions.append({'flow': fid, 'epoch': fl['epoch'],
                                      'release': fl['release'], 'at': at,
                                      'seen': fl['consumed'], 'class': cls,
                                      'reason': 'close', 'rule': None, 'start': None})
                rel = fl['release']
                pins[rel] -= 1
                if pins[rel] == 0 and rel != current:
                    residents.pop(rel, None)
                del flows[fid]
            at += 1
    if flows:
        raise Invalid()
    return installs, decisions, {'current': current, 'resident': sorted(residents),
                                 'used': usage(residents)}


# ---------------- top level ----------------

def response(request):
    try:
        return _response(request)
    except Invalid:
        return {'error': 'invalid_request'}


def _response(request):
    catalog = []
    models = {}
    total_frags = 0
    for spec in request['releases']:
        width = spec['width']
        frag = fragments_of(spec['discovery'], width)
        total_frags += len(frag)
        if total_frags > 4096:
            raise Invalid()
        clusters, noise = cluster_all(frag, spec['eps'], spec['ratio'])
        priority = calibrate(clusters, spec['validation'], spec['classes'], spec['threshold'])
        by_id = {c['id']: c for c in clusters}
        kept = [by_id[cid] for cid in priority]
        backup = backup_cert(spec['train'], width)
        entries = entry_count(kept, spec['mode'], request['capacity']['exact'])
        models[spec['id']] = {'width': width, 'packet_limit': spec['packet_limit'],
                              'idle_us': spec['idle_us'], 'mode': spec['mode'],
                              'entries': entries, 'backup': backup,
                              'kept': [(c['id'], c['class'], c['range']) for c in kept]}
        catalog.append({
            'id': spec['id'],
            'fragments': [list(f[0]) for f in frag],
            'noise': noise,
            'clusters': [{'id': c['id'], 'class': c['class'], 'members': c['members'],
                          'core': c['core'], 'range': c['range'], 'hits': c['hits'],
                          'score': [c['score'].numerator, c['score'].denominator],
                          'kept': c['kept']} for c in clusters],
            'priority': priority,
            'backup': backup,
            'entries': entries})
    installs, decisions, final = replay(models, request['blocks'], request['capacity'])
    return {'catalog': catalog, 'installs': installs, 'decisions': decisions, 'final': final}
